    /** 模型名 → 品牌键。按顺序匹配，越具体的放越前面；未知回退 GPT。 */
    fun resolveKey(modelName: String?): String {
        val name = modelName.orEmpty().lowercase()
        if (name.isEmpty()) return "gpt"
        val rules = listOf(
            listOf("deepseek") to "deepseek",
            listOf("mimo", "小米") to "mimo",
            listOf("claude", "anthropic", "sonnet", "opus", "haiku") to "claude",
            listOf("gemini", "gemma", "google") to "gemini",
            listOf("qwen", "tongyi", "通义", "qwq") to "qwen",
            listOf("kimi", "moonshot", "月之暗面") to "kimi",
            listOf("glm", "chatglm", "zhipu", "智谱", "zai", "z.ai") to "glm",
            listOf("minimax", "abab") to "minimax",
            listOf("step-", "stepfun", "step1", "step2", "step3", "阶跃") to "step",
            listOf("hunyuan", "tencent", "混元", "hy-") to "hunyuan",
            listOf("doubao", "豆包", "volc", "ark") to "doubao",
            listOf("llama", "meta", "mistral", "mixtral", "grok", "x-ai", "xai", "ollama", "ernie", "文心", "baidu") to "gpt",
        )
        for ((keywords, key) in rules) {
            if (keywords.any { name.contains(it) }) return key
        }
        return "gpt"
    }

    private val cache = mutableMapOf<String, Pair<Path, Float>>()

    fun brandPath(modelName: String?): Pair<Path, Float> {
        val key = resolveKey(modelName)
        return cache.getOrPut(key) {
            val brand = brands[key] ?: brands.getValue("gpt")
            parser.parsePathString(brand.pathData).toPath() to brand.viewport
        }
    }
}

/**
 * 绘制品牌标识。图形按原始视窗等比缩放到 [size]，颜色为 [color]。
 */
@Composable
fun BrandBadge(
    modelName: String?,
    size: androidx.compose.ui.unit.Dp,
    color: Color,
    modifier: Modifier = Modifier,
) {
    Canvas(modifier = modifier.requiredSize(size)) {
        val (path, viewport) = BrandIcons.brandPath(modelName)
        val factor = this.size.minDimension / viewport
        val dx = (this.size.width - viewport * factor) / 2f
        val dy = (this.size.height - viewport * factor) / 2f
        withTransform({
            translate(dx, dy)
            scale(factor, factor, pivot = Offset.Zero)
        }) {
            drawPath(path = path, color = color)
        }
    }
}
